source.exploreUrl:
@js:

let sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexBasisPercent: type
    }
});
    push('番茄书架', 'https://fanqienovel.com/reading/bookapi/bookshelf/info/v:version/?aid=1967&iid=0&version_code=56910&update_version_code=56910', 1);
    push('巅峰榜单', 'https://fanqienovel.com/api/author/misc/top_book_list/v1/?limit=100&offset=0', 0.29);
    push('出版榜单', 'https://fanqienovel.com/api/node/publication/list?page_index=0&page_count=100', 0.29);
    push('爆更榜单', 'https://api-lf.fanqiesdk.com/api/novel/channel/homepage/rank/rank_list/v2/?aid=13&limit=50&offset=0&side_type=15&type=1', 0.29);
    push('黑马榜单', 'https://api-lf.fanqiesdk.com/api/novel/channel/homepage/rank/rank_list/v2/?aid=13&limit=50&offset=0&side_type=13&type=1', 0.29);
    push('热搜榜单', 'https://api-lf.fanqiesdk.com/api/novel/channel/homepage/rank/rank_list/v2/?aid=13&limit=50&offset=&side_type=12&type=1', 0.29);	
    push('每周推荐', 'https://fanqienovel.com/api/rank/recommend/list?type=1&limit=10&offset=0', 0.29);	

	A=[["推荐","10"],["完结","11"],["热搜","12"]]	;
[["男频","1"],["女频","0"]].map([title,id]=>{
	push('❤️'+title+'榜单❤️', null, 1);
	if(id==2){ 	A=A.slice(1,A.length-1) }
		A.map([title,uri]=>{			
		  	url= `https://novel.snssdk.com/api/novel/channel/homepage/rank/rank_list/v2/?aid=13&app_name=news_article&app_version=9.7.3&channel=tengxun_tt&device_platform=android&os=android&device_type=ProjectTitan&os_api=29&os_version=10&openlive_plugin_status=1&isTTWebViewHeifSupport=0&limit=100&offset={{(page-1)*100}}&side_type=${uri}&type=${id}`;
				push(title, url, 0.29);			
			});
	});	

	category = () =>{
			category_url = "https://novel.snssdk.com/api/novel/channel/homepage/new_category/page/data/v1/?aid=13";
return  JSON.parse(java.ajax(category_url)).data		
		}

  json = (data) => {
     boy = data.boy_category;
     girl = data.girl_category;
     publish = data.publish_category;
     json = [["男频","gender=1",boy],["女频","gender=0",girl],["出版","genre_type=160",publish]];
     return JSON.parse(JSON.stringify(json));
   }	
		json(category()).map([tit1,gender,category]=>{
	    push('❤️'+tit1+'❤️', null, 1);
     category.map(($,index)=>{
     	index++;
	    title = $.category_name;
     	cid = $.category_id;
	    url=  `https://novel.snssdk.com/api/novel/channel/homepage/new_category/book_list/v1/?aid=1967&app_name=news_article&app_version=9.7.3&channel=tengxun_tt&creation_status=9&device_platform=android&enter_from=novel_category&novel_host&novel_version&version_code=973&version_name=9.7.3&word_count=9&os=android&device_type=ProjectTitan&os_api=29&os_version=10&offset={{(page-1)*100}}&limit=100&category_id=${cid}&${gender}`;
				push(title, url, 0.29);	
      });
  });
JSON.stringify(sort);

